      lat: la / n, lon: lo / n, start: start, stops: stops, count: s.stops.length,
      kmText: s.distance, timeText: walkText(s), theme: s.tags.map(function (t) { return t.label; }),
      legs: s.stops.slice(0, -1).map(function (t) { return { metres: t.toNext.m, minutes: t.toNext.min }; }),
      hook: s.hook, cover: s.cover || '', coverAlt: s.coverAlt, scene: s.scene, transit: tr,
